import type { Query } from "reylo";
export type Params = { ids: number[] };
export type Row = { id: number; name: string };
export declare const sql: "-- SQLite has no array type, so the list is a JSON parameter
with input as (
  select ? as ids
)
select id, name from users
where id in (select j.value from input, json_each(input.ids) as j)
";
